package com.pulsepay.payment;
import com.pulsepay.config.FinancialMetrics; import java.util.*; import java.util.concurrent.ThreadLocalRandom; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class PaymentSimulator {
 private final JdbcTemplate db; private final String defaultOutcome; private final boolean randomOutcomes; private final FinancialMetrics metrics;
 public PaymentSimulator(JdbcTemplate db,String defaultOutcome,boolean randomOutcomes){this(db,defaultOutcome,randomOutcomes,null);}
 @Autowired public PaymentSimulator(JdbcTemplate db,@Value("${pulsepay.simulator.default-outcome:success}")String defaultOutcome,@Value("${pulsepay.simulator.random-outcomes-enabled:false}")boolean randomOutcomes,FinancialMetrics metrics){this.db=db;this.defaultOutcome=defaultOutcome;this.randomOutcomes=randomOutcomes;this.metrics=metrics;}
 @Scheduled(fixedDelay=1500) @Transactional public void process(){var ids=db.query("select id from payment_intents where status='PROCESSING' order by created_at limit 20 for update skip locked",(rs,i)->UUID.fromString(rs.getString(1)));for(UUID id:ids){var rows=db.query("select merchant_id,amount_minor,coalesce(description,''),metadata::text,processing_attempts from payment_intents where id=? for update",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getLong(2),rs.getString(3),rs.getString(4),rs.getInt(5)},id);if(rows.isEmpty())continue;Object[] r=rows.getFirst();int attempt=(Integer)r[4]+1;String outcome=outcome((String)r[2],(String)r[3]);db.update("update payment_intents set processing_attempts=?,updated_at=now() where id=?",attempt,id);if(("temporary_failure".equals(outcome)||"timeout".equals(outcome))&&attempt<2)continue;boolean failed=Set.of("decline","timeout","temporary_failure").contains(outcome);String event;if(failed){db.update("update payment_intents set status='FAILED',updated_at=now() where id=?",id);event="payment.failed";}else{db.update("update payment_intents set status='SUCCEEDED',updated_at=now() where id=?",id);db.update("insert into authorizations(payment_intent_id,authorized_minor,status)values(?,?,'AUTHORIZED') on conflict (payment_intent_id) do nothing",id,r[1]);event="payment.succeeded";}if(metrics!=null)metrics.paymentOutcome(failed?"failed":"succeeded");db.update("insert into outbox_events(merchant_id,aggregate_type,aggregate_id,event_type,correlation_id,payload)values(?,'payment_intent',?,?,gen_random_uuid(),jsonb_build_object('payment_intent_id',?,'simulate_duplicate_delivery',?))",r[0],id,event,id,"duplicate_event".equals(outcome));}}
 String outcome(String description,String metadata){String explicit=metadata.replaceFirst(".*\\\"test_outcome\\\"\\s*:\\s*\\\"([^\\\"]+).*","$1");if(!explicit.equals(metadata))return explicit.toLowerCase(Locale.ROOT);if(description.toLowerCase(Locale.ROOT).contains("decline"))return "decline";if(randomOutcomes)return ThreadLocalRandom.current().nextInt(10)==0?"decline":"success";return defaultOutcome.toLowerCase(Locale.ROOT);}
}
